 function addTask(state,title,minutes=20,details={}){title=String(title||'').trim().slice(0,120);if(!title)return null;const date=validDate(details.date)?details.date:todayKey();if(details.dedupe){const old=state.tasks.find(t=>t.date===date&&t.title===title&&t.sourceType===details.sourceType&&t.sourceId===details.sourceId);if(old)return old;}const task={id:id('task'),title,minutes:Math.min(180,Math.max(5,Number(minutes)||20)),tag:str(details.tag,80)||'我的安排',body:str(details.body)||'你添加的本地任务。',evidence:str(details.evidence),date,doneAt:null,sourceType:str(details.sourceType,40)||'manual',sourceId:str(details.sourceId,150),resultNote:str(details.resultNote),resultEvidence:str(details.resultEvidence),verificationStatus:verification(details.verificationStatus)};state.tasks.push(task);return task;}
